package lk.medical.service;
import lk.medical.model.*; import org.springframework.stereotype.Service; import java.time.*; import java.util.*; import java.util.stream.*;
@Service public class MedicalService { private final TextFileStore store; public MedicalService(TextFileStore store){this.store=store;seed();} private void seed(){if(store.read("users.txt").isEmpty()){store.write("users.txt",List.of(userLine(new PatientUser("P100","Demo Patient","patient@demo.com","patient123","0771234567","Negombo","Asthma")),userLine(new AdminUser("A100","System Admin","admin@demo.com","admin123"))));}if(store.read("doctors.txt").isEmpty()){store.write("doctors.txt",List.of(doctorLine(new GeneralPractitioner("D100","Dr. Amara Perera","General Medicine","Mon-Fri 09:00-13:00","101","doctor@demo.com","doctor123",2500)),doctorLine(new SpecialistDoctor("D101","Dr. Nimal Silva","Cardiology","Tue/Thu 14:00-18:00","204","cardio@demo.com","doctor123",4500))));}}
 private String userLine(User u){String extra=u instanceof PatientUser p?p.getMedicalHistory():u instanceof DoctorUser d?d.getSpecialization():"";return String.join("|",TextFileStore.enc(u.getId()),TextFileStore.enc(u.getFullName()),TextFileStore.enc(u.getEmail().toLowerCase()),TextFileStore.enc(u.getPassword()),TextFileStore.enc(u.getPhone()),TextFileStore.enc(u.getAddress()),u.getRole(),TextFileStore.enc(extra));}
 private User parseUser(String line){String[] a=line.split("\\|",-1);String id=TextFileStore.dec(a[0]),n=TextFileStore.dec(a[1]),e=TextFileStore.dec(a[2]),p=TextFileStore.dec(a[3]),ph=TextFileStore.dec(a[4]),ad=TextFileStore.dec(a[5]),extra=TextFileStore.dec(a[7]);return switch(a[6]){case "PATIENT"->new PatientUser(id,n,e,p,ph,ad,extra);case "DOCTOR"->new DoctorUser(id,n,e,p,ph,ad,extra);default->new AdminUser(id,n,e,p);};}
 private String doctorLine(Doctor d){return String.join("|",TextFileStore.enc(d.getId()),TextFileStore.enc(d.getName()),TextFileStore.enc(d.getSpecialization()),TextFileStore.enc(d.getAvailability()),TextFileStore.enc(d.getRoomNumber()),TextFileStore.enc(d.getEmail()),TextFileStore.enc(d.getPassword()),Double.toString(d.getFee()),d.getType());}
 private Doctor parseDoctor(String line){String[] a=line.split("\\|",-1);String id=TextFileStore.dec(a[0]),n=TextFileStore.dec(a[1]),s=TextFileStore.dec(a[2]),av=TextFileStore.dec(a[3]),room=TextFileStore.dec(a[4]),email=TextFileStore.dec(a[5]),pw=TextFileStore.dec(a[6]);double fee=Double.parseDouble(a[7]);return "SPECIALIST".equals(a[8])?new SpecialistDoctor(id,n,s,av,room,email,pw,fee):new GeneralPractitioner(id,n,s,av,room,email,pw,fee);}
 private String appointmentLine(Appointment a){return String.join("|",TextFileStore.enc(a.getId()),TextFileStore.enc(a.getPatientId()),TextFileStore.enc(a.getDoctorId()),a.getDate().toString(),a.getTime().toString(),a.getStatus(),TextFileStore.enc(a.getReason()),TextFileStore.enc(a.getNotes()),TextFileStore.enc(a.getFeedback()));}
 private Appointment parseAppointment(String l){String[] a=l.split("\\|",-1);return new Appointment(TextFileStore.dec(a[0]),TextFileStore.dec(a[1]),TextFileStore.dec(a[2]),LocalDate.parse(a[3]),LocalTime.parse(a[4]),a[5],TextFileStore.dec(a[6]),TextFileStore.dec(a[7]),TextFileStore.dec(a[8]));}
 public List<Doctor> doctors(String q){String needle=Objects.toString(q,"").trim().toLowerCase(Locale.ROOT);return store.read("doctors.txt").stream().map(this::parseDoctor).filter(d->d.getName().toLowerCase(Locale.ROOT).contains(needle)||d.getSpecialization().toLowerCase(Locale.ROOT).contains(needle)).toList();}
 public Optional<Doctor> doctor(String id){String wanted=Objects.toString(id,"").trim();return doctors("").stream().filter(d->d.getId().equals(wanted)).findFirst();}
 public void saveDoctor(String id,String name,String spec,String availability,String room,double fee,String type,String email,String password){
  String cleanId=Objects.toString(id,"").trim();String cleanName=Objects.toString(name,"").trim();String cleanSpec=Objects.toString(spec,"").trim();String cleanAvailability=Objects.toString(availability,"").trim();String cleanRoom=Objects.toString(room,"").trim();String cleanEmail=Objects.toString(email,"").trim().toLowerCase(Locale.ROOT);String cleanType="SPECIALIST".equals(type)?"SPECIALIST":"GP";
  if(cleanName.isBlank()||cleanSpec.isBlank()||cleanAvailability.isBlank()||cleanRoom.isBlank()||cleanEmail.isBlank())throw new IllegalArgumentException("Please complete all required doctor details.");
  if(!cleanEmail.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$"))throw new IllegalArgumentException("Enter a valid doctor email address.");
  if(!Double.isFinite(fee)||fee<0)throw new IllegalArgumentException("Consultation fee must be zero or greater.");
  List<String> all=store.read("doctors.txt");Doctor existing=all.stream().map(this::parseDoctor).filter(d->d.getId().equals(cleanId)&&!cleanId.isBlank()).findFirst().orElse(null);
  String cleanPassword=Objects.toString(password,"");if(existing!=null&&cleanPassword.isBlank())cleanPassword=existing.getPassword();
  if(cleanPassword.length()<6)throw new IllegalArgumentException("Doctor password must contain at least 6 characters.");
  final String idToSave=cleanId.isBlank()?"D"+UUID.randomUUID().toString().substring(0,8):cleanId;
  boolean duplicateDoctor=all.stream().map(this::parseDoctor).anyMatch(d->!d.getId().equals(idToSave)&&d.getEmail().equalsIgnoreCase(cleanEmail));
  boolean duplicateUser=store.read("users.txt").stream().map(this::parseUser).anyMatch(u->u.getEmail().equalsIgnoreCase(cleanEmail));
  if(duplicateDoctor||duplicateUser)throw new IllegalArgumentException("That email address is already used by another account.");
  Doctor d="SPECIALIST".equals(cleanType)?new SpecialistDoctor(idToSave,cleanName,cleanSpec,cleanAvailability,cleanRoom,cleanEmail,cleanPassword,fee):new GeneralPractitioner(idToSave,cleanName,cleanSpec,cleanAvailability,cleanRoom,cleanEmail,cleanPassword,fee);
  all.removeIf(line->parseDoctor(line).getId().equals(idToSave));all.add(doctorLine(d));store.write("doctors.txt",all);
 }
 public void deleteDoctor(String id){store.write("doctors.txt",store.read("doctors.txt").stream().filter(l->!parseDoctor(l).getId().equals(id)).toList());}
 public User register(String name,String email,String password,String phone,String address){if(name.isBlank()||email.isBlank()||password.length()<6)throw new IllegalArgumentException("Name/email required and password must be at least 6 characters.");if(store.read("users.txt").stream().map(this::parseUser).anyMatch(u->u.getEmail().equalsIgnoreCase(email)))throw new IllegalArgumentException("Email already registered.");PatientUser p=new PatientUser("P"+UUID.randomUUID().toString().substring(0,8),name,email,password,phone,address,"");List<String> all=store.read("users.txt");all.add(userLine(p));store.write("users.txt",all);return p;}
 public User login(String email,String password,String role){if("DOCTOR".equals(role)){return doctors("").stream().filter(d->d.getEmail().equalsIgnoreCase(email)&&d.getPassword().equals(password)).findFirst().map(d->(User)new DoctorUser(d.getId(),d.getName(),d.getEmail(),d.getPassword(),"","",d.getSpecialization())).orElse(null);}return store.read("users.txt").stream().map(this::parseUser).filter(u->u.getEmail().equalsIgnoreCase(email)&&u.getRole().equals(role)&&u.authenticate(password)).findFirst().orElse(null);}
 public List<Appointment> appointments(){return store.read("appointments.txt").stream().map(this::parseAppointment).sorted(Comparator.comparing(Appointment::getDate).thenComparing(Appointment::getTime)).toList();} public List<Appointment> appointmentsFor(User u){return appointments().stream().filter(a->u.getRole().equals("ADMIN")||("PATIENT".equals(u.getRole())&&a.getPatientId().equals(u.getId()))||("DOCTOR".equals(u.getRole())&&a.getDoctorId().equals(u.getId()))).toList();}
 public void book(String patient,String doctor,LocalDate date,LocalTime time,String reason){if(date.isBefore(LocalDate.now()))throw new IllegalArgumentException("Past appointments cannot be booked.");if(doctor(doctor).isEmpty())throw new IllegalArgumentException("Please choose a valid doctor.");if(appointments().stream().anyMatch(a->a.getDoctorId().equals(doctor)&&a.getDate().equals(date)&&a.getTime().equals(time)&&!a.getStatus().equals("CANCELLED")))throw new IllegalArgumentException("This doctor already has an appointment at that time.");Appointment a=new Appointment("AP"+UUID.randomUUID().toString().substring(0,8),patient,doctor,date,time,"PENDING",reason,"","");List<String> all=store.read("appointments.txt");all.add(appointmentLine(a));store.write("appointments.txt",all);}
 public void updateAppointment(String id,String action,LocalDate date,LocalTime time,String note,String feedback,User actor){List<String> lines=store.read("appointments.txt");boolean found=false;for(int i=0;i<lines.size();i++){Appointment a=parseAppointment(lines.get(i));if(!a.getId().equals(id))continue;if(!actor.getRole().equals("ADMIN")&&!a.getPatientId().equals(actor.getId())&&!a.getDoctorId().equals(actor.getId()))throw new IllegalArgumentException("Not authorised.");if("CANCELLED".equals(action)){a.setStatus("CANCELLED");}else if("RESCHEDULE".equals(action)){if(date==null||time==null||date.isBefore(LocalDate.now()))throw new IllegalArgumentException("Choose a valid future date/time.");if(appointments().stream().anyMatch(x->!x.getId().equals(id)&&x.getDoctorId().equals(a.getDoctorId())&&x.getDate().equals(date)&&x.getTime().equals(time)&&!x.getStatus().equals("CANCELLED")))throw new IllegalArgumentException("That slot is already booked.");a.setDate(date);a.setTime(time);a.setStatus("PENDING");}else if("CONFIRMED".equals(action)||"COMPLETED".equals(action)||"PENDING".equals(action)){a.setStatus(action);}else if("RECORD".equals(action)){a.setNotes(note);a.setFeedback(feedback);}else throw new IllegalArgumentException("Unknown action.");lines.set(i,appointmentLine(a));found=true;break;}if(!found)throw new IllegalArgumentException("Appointment not found.");store.write("appointments.txt",lines);}
 public String patientName(String id){return store.read("users.txt").stream().map(this::parseUser).filter(u->u.getId().equals(id)).map(User::getFullName).findFirst().orElse(id);} public String doctorName(String id){return doctor(id).map(Doctor::getName).orElse(id);} public String patientEmail(String id){return store.read("users.txt").stream().map(this::parseUser).filter(u->u.getId().equals(id)).map(User::getEmail).findFirst().orElse("");} public List<MedicalRecord> recordsFor(User u){return appointmentsFor(u).stream().filter(a->!a.getNotes().isBlank()||!a.getFeedback().isBlank()).map(a->new MedicalRecord(a.getId(),a.getId(),a.getPatientId(),a.getDoctorId(),a.getNotes(),a.getFeedback(),LocalDateTime.of(a.getDate(),a.getTime()))).toList();} public void deletePatient(String id){store.write("users.txt",store.read("users.txt").stream().filter(l->!parseUser(l).getId().equals(id)).toList());store.write("appointments.txt",appointments().stream().filter(a->!a.getPatientId().equals(id)).map(this::appointmentLine).toList());} public List<User> patients(){return store.read("users.txt").stream().map(this::parseUser).filter(u->u instanceof PatientUser).toList();}
}
